do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$0992$q$,$q$Lenovo Group$q$,null,null,true,false,array[$q$HKEX$q$]::text[],$q$HKEX 0992$q$,$q$HK$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$AMD$q$,$q$public_company$q$),($q$Alat Technologies$q$,$q$private_company$q$),($q$AleveR Robotics$q$,$q$private_company$q$),($q$Compal Electronics$q$,$q$public_company$q$),($q$DreamWorks$q$,$q$private_company$q$),($q$FIFA$q$,$q$organization$q$),($q$Formula 1$q$,$q$private_company$q$),($q$Fujitsu$q$,$q$public_company$q$),($q$Fujitsu Client Computing Limited$q$,$q$private_company$q$),($q$Fujitsu Isotec$q$,$q$private_company$q$),($q$Hefei Zhi Ju Sheng Bao Equity Investment$q$,$q$private_company$q$),($q$Infinidat$q$,$q$private_company$q$),($q$Intel$q$,$q$public_company$q$),($q$JV Co$q$,$q$private_company$q$),($q$Legend Holdings$q$,$q$public_company$q$),($q$Lenovo NEC Holdings B.V.$q$,$q$private_company$q$),($q$Microsoft$q$,$q$public_company$q$),($q$NEC$q$,$q$public_company$q$),($q$NVIDIA$q$,$q$public_company$q$),($q$Nscale$q$,$q$private_company$q$),($q$PCCW Solutions$q$,$q$private_company$q$),($q$Public Investment Fund$q$,$q$institution$q$),($q$Qualcomm$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$As DreamWorks’ preferred compute services, solutions, and workstation provider, Lenovo supports every stage of the production process.$q$),(2,$q$As at March 31, 2026, Legend Holdings, together with Right Lane, Kind Jasper, Legion Elite and Honorific Promise, directly or indirectly held 32.04% ordinary shares of the Company.$q$),(3,$q$As the Official Technology Partner of FIFA, Lenovo is powering the biggest event in the history of humanity; the FIFA World Cup 2026™.$q$),(4,$q$At March 31, 2026 and 2025, the Group held 95.10% in the ordinary shares of Lenovo NEC Holdings B.V., the immediate holding company of Lenovo Japan LLC and NEC Personal Computers, Ltd., while the remaining 4.90% ordinary shares and 42,700 deferred shares of Lenovo NEC Holdings B.V. were held by NEC Corporation.$q$),(5,$q$At or prior to the completion of the FCCL joint venture taking place on May 2, 2018, FCCL entered into various agreements with members of the Fujitsu Group to facilitate the operation of its business.$q$),(6,$q$By virtue of the SFO, Alat Technologies and PI Fund are deemed to be interested in the 1,559,181,636 ordinary shares held by Alat International.$q$),(7,$q$During the year ended March 31, 2019, Hefei Zhi Ju Sheng Bao Equity Investment Co., Ltd (“ZJSB”) acquired the 49% interest in a joint venture company (“JV Co”) from Compal Electronics, Inc.$q$),(8,$q$From the racetrack to the Media & Technology Centre in Biggin Hill, UK, Lenovo provides the AI devices, innovative solutions, and robust IT infrastructure that support everyone, from executives to trackside operational engineers.$q$),(9,$q$Fujitsu Client Computing Limited (“FCCL”) is an indirect non-wholly-owned subsidiary of the Company, held as to 51% by the Group and 49% by Fujitsu.$q$),(10,$q$Fujitsu currently owns 49% interest in FCCL.$q$),(11,$q$In 2025, Lenovo extended its technology partnership with Formula 1®, becoming a Global Partner of the organization.$q$),(12,$q$In November 2025, directors were invited to visit the headquarters of Lenovo’s key business partner, NVIDIA, in California, the United States.$q$),(13,$q$Nscale selected Lenovo and NVIDIA to help deploy the site, with the goal of improving the responsiveness of its AI solutions and reducing time to value for customers.$q$),(14,$q$On April 9, 2026, the Group completed the acquisition of 100% interests in Infinidat Ltd. (“Infinidat”).$q$),(15,$q$PCCW Solutions Limited (a subsidiary of an associate) — Services received$q$),(16,$q$Pursuant to the joint venture agreement entered into between the Company and Fujitsu Limited (“Fujitsu”), the Company and Fujitsu are respectively granted call and put options which entitle the Company to purchase from Fujitsu and Development Bank of Japan (“DBJ”), or Fujitsu and DBJ to sell to the Company, the 49% interest in Fujitsu Client Computing Limited and its subsidiaries (together “FCCL”).$q$),(17,$q$Pursuant to the joint venture agreement entered into with NEC Corporation, the Group is required to pay in cash to NEC Corporation deferred consideration.$q$),(18,$q$Services provided/received: FCCL agreed to supply Fujitsu-branded products and such other products as agreed between the parties and services to Fujitsu.$q$),(19,$q$Services provided/received: FIT agreed to provide manufacturing services to FCCL.$q$),(20,$q$Services provided/received: Fujitsu granted FCCL licenses to use Fujitsu name and trademarks.$q$),(21,$q$The Group holds 12.4% (2025: 11.6%) equity interest in AleveR Robotics Limited and is considered to have significant influence through its participation in the board of directors.$q$),(22,$q$The Infinidat acquisition, completed in early April, further strengthened the Group’s position in high-end enterprise storage, expanding both in its addressable market and long-term margins opportunities.$q$),(23,$q$The chief executive officers and senior leaders of Lenovo’s key business partners and industry peers, including AMD, FIFA, Intel, Microsoft, NVIDIA and Qualcomm, also joined Lenovo’s senior leadership team on stage.$q$),(24,$q$The shareholding structure of the Company as of March 31, 2026 is illustrated as follows: 32.04% Legend Holdings Corporation Note 1 Mr. Yang Note 2 61.05% Other directors Note 3 6.15% Others Note 4 0.76%$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$sells_to$q$,$q$0992$q$,$q$DreamWorks$q$,$q${1}$q$::int[],$q${p4}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$0992$q$,$q$FIFA$q$,$q${3,23}$q$::int[],$q${p8,p79}$q$::text[],null,null,null,null),(3,$q$sells_to$q$,$q$0992$q$,$q$Nscale$q$,$q${13}$q$::int[],$q${p17}$q$::text[],null,null,null,null),(4,$q$partners$q$,$q$0992$q$,$q$NVIDIA$q$,$q${13,12}$q$::int[],$q${p17,p81}$q$::text[],null,null,null,null),(5,$q$acquires$q$,$q$0992$q$,$q$Infinidat$q$,$q${22,14}$q$::int[],$q${p20,p268}$q$::text[],null,null,null,null),(6,$q$sells_to$q$,$q$0992$q$,$q$Formula 1$q$,$q${8}$q$::int[],$q${p59}$q$::text[],null,null,null,null),(7,$q$partners$q$,$q$0992$q$,$q$Formula 1$q$,$q${11}$q$::int[],$q${p80}$q$::text[],null,null,null,null),(8,$q$partners$q$,$q$0992$q$,$q$AMD$q$,$q${23}$q$::int[],$q${p79}$q$::text[],null,null,null,null),(9,$q$partners$q$,$q$0992$q$,$q$Intel$q$,$q${23}$q$::int[],$q${p79}$q$::text[],null,null,null,null),(10,$q$partners$q$,$q$0992$q$,$q$Microsoft$q$,$q${23}$q$::int[],$q${p79}$q$::text[],null,null,null,null),(11,$q$partners$q$,$q$0992$q$,$q$Qualcomm$q$,$q${23}$q$::int[],$q${p79}$q$::text[],null,null,null,null),(12,$q$invests$q$,$q$Legend Holdings$q$,$q$0992$q$,$q${24,2}$q$::int[],$q${p118,p162}$q$::text[],32.04,$q$approximate$q$,$q$ownership$q$,null),(13,$q$invests$q$,$q$Alat Technologies$q$,$q$0992$q$,$q${6}$q$::int[],$q${p162}$q$::text[],null,null,null,null),(14,$q$invests$q$,$q$Public Investment Fund$q$,$q$0992$q$,$q${6}$q$::int[],$q${p162}$q$::text[],null,null,null,null),(15,$q$invests$q$,$q$Fujitsu$q$,$q$Fujitsu Client Computing Limited$q$,$q${9,10}$q$::int[],$q${p165,p224}$q$::text[],49,$q$exact$q$,$q$ownership$q$,null),(16,$q$partners$q$,$q$0992$q$,$q$Fujitsu$q$,$q${5,16}$q$::int[],$q${p165,p224}$q$::text[],null,null,null,null),(17,$q$sells_to$q$,$q$0992$q$,$q$Fujitsu$q$,$q${18}$q$::int[],$q${p167}$q$::text[],null,null,null,null),(18,$q$supplies$q$,$q$Fujitsu$q$,$q$0992$q$,$q${20}$q$::int[],$q${p168}$q$::text[],null,null,null,null),(19,$q$supplies$q$,$q$Fujitsu Isotec$q$,$q$0992$q$,$q${19}$q$::int[],$q${p167}$q$::text[],null,null,null,null),(20,$q$partners$q$,$q$0992$q$,$q$NEC$q$,$q${17}$q$::int[],$q${p231}$q$::text[],null,null,null,null),(21,$q$invests$q$,$q$0992$q$,$q$AleveR Robotics$q$,$q${21}$q$::int[],$q${p213}$q$::text[],12.4,$q$exact$q$,$q$ownership$q$,null),(22,$q$acquires$q$,$q$Hefei Zhi Ju Sheng Bao Equity Investment$q$,$q$JV Co$q$,$q${7}$q$::int[],$q${p224}$q$::text[],49,$q$exact$q$,$q$ownership$q$,null),(23,$q$invests$q$,$q$NEC$q$,$q$Lenovo NEC Holdings B.V.$q$,$q${4}$q$::int[],$q${p267}$q$::text[],4.9,$q$exact$q$,$q$ownership$q$,null),(24,$q$supplies$q$,$q$PCCW Solutions$q$,$q$0992$q$,$q${15}$q$::int[],$q${p258}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Lyft$q$ then ticker=$q$LYFT$q$ when $q$DoorDash$q$ then ticker=$q$DASH$q$ when $q$0992$q$ then ticker=$q$0992$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$Lenovo 2025/26 Annual Report (M15)$q$,'claude-sonnet-5-5 via Claude Code session',1.1252,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2026-03-31$q$::date end,$q$annual_report$q$,$q$staged$q$,null,run_id,$q$2026-03-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,null,r.sec[k],t,true,null from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
